import datetime
import unittest

from daterange import parse_range


D = datetime.date


class TestClosedRanges(unittest.TestCase):
    def test_two_dates(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31))
        )

    def test_same_day(self):
        self.assertEqual(parse_range("2026-10-01..2026-10-01"), (D(2026, 10, 1), D(2026, 10, 1)))

    def test_across_month_and_year(self):
        self.assertEqual(parse_range("2026-02-28..2026-03-01"), (D(2026, 2, 28), D(2026, 3, 1)))
        self.assertEqual(parse_range("2025-12-31..2026-01-01"), (D(2025, 12, 31), D(2026, 1, 1)))

    def test_period_endpoints(self):
        self.assertEqual(parse_range("2026-10..2026-11"), (D(2026, 10, 1), D(2026, 11, 30)))
        self.assertEqual(parse_range("2026..2026-06-30"), (D(2026, 1, 1), D(2026, 6, 30)))
        self.assertEqual(parse_range("2026-01-01..2026"), (D(2026, 1, 1), D(2026, 12, 31)))
        self.assertEqual(parse_range("2026-W44..2026-11-01"), (D(2026, 10, 26), D(2026, 11, 1)))

    def test_end_on_period_boundary(self):
        self.assertEqual(parse_range("2026-10-31..2026-10"), (D(2026, 10, 31), D(2026, 10, 31)))

    def test_reversed_dates_rejected(self):
        with self.assertRaises(ValueError):
            parse_range("2026-11-01..2026-10-01")
        with self.assertRaises(ValueError):
            parse_range("2026-10-01..2025-12-31")

    def test_reversed_periods_rejected(self):
        with self.assertRaises(ValueError):
            parse_range("2026-11..2026-10")
        with self.assertRaises(ValueError):
            parse_range("2026..2025")
        with self.assertRaises(ValueError):
            parse_range("2026-W45..2026-W44")


class TestPeriodTokens(unittest.TestCase):
    def test_month(self):
        self.assertEqual(parse_range("2026-10"), (D(2026, 10, 1), D(2026, 10, 31)))
        self.assertEqual(parse_range("2026-12"), (D(2026, 12, 1), D(2026, 12, 31)))

    def test_february_lengths(self):
        self.assertEqual(parse_range("2024-02"), (D(2024, 2, 1), D(2024, 2, 29)))
        self.assertEqual(parse_range("2026-02"), (D(2026, 2, 1), D(2026, 2, 28)))

    def test_week(self):
        self.assertEqual(parse_range("2026-W44"), (D(2026, 10, 26), D(2026, 11, 1)))

    def test_week_crossing_year(self):
        self.assertEqual(parse_range("2026-W01"), (D(2025, 12, 29), D(2026, 1, 4)))

    def test_week_53(self):
        self.assertEqual(parse_range("2026-W53"), (D(2026, 12, 28), D(2027, 1, 3)))

    def test_year(self):
        self.assertEqual(parse_range("2026"), (D(2026, 1, 1), D(2026, 12, 31)))
        self.assertEqual(parse_range("2024"), (D(2024, 1, 1), D(2024, 12, 31)))

    def test_single_date(self):
        self.assertEqual(parse_range("2026-10-01"), (D(2026, 10, 1), D(2026, 10, 1)))


class TestOpenEnds(unittest.TestCase):
    def test_open_start(self):
        self.assertEqual(parse_range("..2026-10-31"), (None, D(2026, 10, 31)))
        self.assertEqual(parse_range("..2026-10"), (None, D(2026, 10, 31)))
        self.assertEqual(parse_range("..2026-W44"), (None, D(2026, 11, 1)))
        self.assertEqual(parse_range("..2026"), (None, D(2026, 12, 31)))

    def test_open_end(self):
        self.assertEqual(parse_range("2026-10-01.."), (D(2026, 10, 1), None))
        self.assertEqual(parse_range("2026-10.."), (D(2026, 10, 1), None))
        self.assertEqual(parse_range("2026-W44.."), (D(2026, 10, 26), None))
        self.assertEqual(parse_range("2026.."), (D(2026, 1, 1), None))

    def test_both_open_rejected(self):
        with self.assertRaises(ValueError):
            parse_range("..")
        with self.assertRaises(ValueError):
            parse_range(" .. ")


class TestWhitespace(unittest.TestCase):
    def test_around_text(self):
        self.assertEqual(
            parse_range("  2026-10-01..2026-10-31  "), (D(2026, 10, 1), D(2026, 10, 31))
        )
        self.assertEqual(parse_range("  2026-10  "), (D(2026, 10, 1), D(2026, 10, 31))

    def test_around_separator(self):
        self.assertEqual(
            parse_range("2026-10-01 .. 2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31))
        )
        self.assertEqual(parse_range("2026-10-01  ..  2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31)))

    def test_around_separator_with_open_end(self):
        self.assertEqual(parse_range("  ..  2026-10-31  "), (None, D(2026, 10, 31)))


class TestMalformed(unittest.TestCase):
    def test_empty(self):
        for text in ("", "   ", "\t", "..", " .. ", "...."):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_bad_dates(self):
        for text in ("2026-02-30", "2026-13-01", "2026-00-01", "0000-01-01", "2026-1-01", "2026-01-1"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_bad_months(self):
        for text in ("2026-13", "2026-00", "2026-1", "0000-01"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_bad_weeks(self):
        for text in ("2026-W54", "2026-W00", "2025-W53", "2026-W4", "2026-w44", "2026-W" ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_bad_years(self):
        for text in ("0000", "26", "20261", "+2026", "-2026"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_missing_or_extra_separator(self):
        for text in (
            "2026-10-012026-10-31",
            "2026-10-01.2026-10-31",
            "2026-10-01...2026-10-31",
            "2026-10-01..2026-10-31..2026-11-01",
            "2026-10-01....2026-10-31",
            "2026-10-01.. ..2026-10-31",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_bad_endpoint(self):
        for text in (
            "2026-10-01..2026-02-30",
            "2026-13..2026-10-01",
            "2026-01-01..2026-W54",
            "2026-10-01..2026-10-31x",
            "x2026-10-01..2026-10-31",
            "2026-10-01..x",
        ):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)

    def test_internal_spaces_rejected(self):
        for text in ("2026 -10-01..2026-10-31", "2026-10-01..2026- 10-31", "2026 - 10"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_range(text)


class TestReturnTypes(unittest.TestCase):
    def test_dates(self):
        start, end = parse_range("2026-10-01..2026-10-31")
        self.assertIs(type(start), datetime.date)
        self.assertIs(type(end), datetime.date)

    def test_none_for_open_ends(self):
        self.assertIsNone(parse_range("..2026-10-31")[0])
        self.assertIsNone(parse_range("2026-10-01..")[1])


if __name__ == "__main__":
    unittest.main()

