class TestClosedRanges(unittest.TestCase):
    def test_two_dates(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31))
        )

    def test_same_day(self):
        self.assertEqual(parse_range("2026-10-01..2026-10-01"), (D(2026, 10, 1), D(2026, 10, 1)))

    def test_across_month_and_year(self):
        self.assertEqual(parse_range("2026-02-28..2026-03-01"), (D(2026, 2, 28), D(2026, 3, 1)))
        self.assertEqual(parse_range("2025-12-31..2026-01-01"), (D(2025, 12, 31), D(2026, 1, 1)))

    def test_period_endpoints(self):
        self.assertEqual(parse_range("2026-10..2026-11"), (D(2026, 10, 1), D(2026, 11, 30)))
        self.assertEqual(parse_range("2026..2026-06-30"), (D(2026, 1, 1), D(2026, 6, 30)))
        self.assertEqual(parse_range("2026-01-01..2026"), (D(2026, 1, 1), D(2026, 12, 31)))
        self.assertEqual(parse_range("2026-W44..2026-11-01"), (D(2026, 10, 26), D(2026, 11, 1)))

    def test_end_on_period_boundary(self):
        self.assertEqual(parse_range("2026-10-31..2026-10"), (D(2026, 10, 31), D(2026, 10, 31)))

    def test_reversed_dates_rejected(self):
        with self.assertRaises(ValueError):
            parse_range("2026-11-01..2026-10-01")
